ng)return;categoryPopup?.Close();Safe(()=>AddModule(d.Id,60+document.CurrentProcedure.Nodes.Count*20,70+document.CurrentProcedure.Nodes.Count*35));};grid.Controls.Add(tile);}if(descriptors.Length==0)grid.Controls.Add(new Label{AutoSize=true,Text="此分类尚未接入独立模块",ForeColor=Color.Gray});if(category=="collection")foreach(var name in new[]{"多图采集","输出图像","缓存图像","光源"}){var tile=new Button{Text="▧\n"+name,Size=new Size(Px(63),Px(85)),Enabled=false,FlatStyle=FlatStyle.Flat,Margin=new Padding(Px(1))};tile.FlatAppearance.BorderSize=0;grid.Controls.Add(tile);}categoryPopup=new ToolStripDropDown{Padding=Padding.Empty,Margin=Padding.Empty,AutoClose=true,BackColor=panel.BackColor};categoryPopup.Items.Add(new ToolStripControlHost(panel){Padding=Padding.Empty,Margin=Padding.Empty});categoryPopup.Show(anchor??graph,anchor is null?new Point(0,0):new Point(anchor.Width,0));}

